class Solution {public:long long maximumStrength(vector<int>& nums,int k){
 const long long NEG=LLONG_MIN/4;vector<long long> done(k+1,NEG),active(k+1,NEG);done[0]=0;
 for(int x:nums){for(int j=k;j>=1;j--){long long w=(long long)(k-j+1)*(j%2?1:-1)*x;
 active[j]=max(active[j],done[j-1])+w;done[j]=max(done[j],active[j]);}}
 return done[k];
}};
